mapper.select:
SELECT DISTINCT ur.user_id FROM sys_user_role ur
JOIN sys_user u ON u.id = ur.user_id AND u.tenant_id = ur.tenant_id
WHERE ur.tenant_id = #{tenantId}
  AND ur.role_id = #{roleId}
  AND u.deleted_at IS NULL
ORDER BY ur.user_id

